CREATE TABLE IF NOT EXISTS departments (id SERIAL PRIMARY KEY, name VARCHAR(80) UNIQUE NOT NULL, description TEXT, head_name VARCHAR(120), created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY, email VARCHAR(160) UNIQUE NOT NULL, password_hash TEXT NOT NULL, role VARCHAR(20) NOT NULL CHECK(role IN ('ADMIN','HR','MANAGER','EMPLOYEE')), first_name VARCHAR(80) NOT NULL, last_name VARCHAR(80) NOT NULL, active BOOLEAN DEFAULT true, created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS employees (id SERIAL PRIMARY KEY, employee_code VARCHAR(20) UNIQUE NOT NULL, user_id INT UNIQUE REFERENCES users(id) ON DELETE SET NULL, first_name VARCHAR(80) NOT NULL, last_name VARCHAR(80) NOT NULL, email VARCHAR(160) UNIQUE NOT NULL, phone VARCHAR(30), dob DATE, gender VARCHAR(20), address TEXT, city VARCHAR(80), state VARCHAR(80), photo_url TEXT, department_id INT REFERENCES departments(id) ON DELETE SET NULL, designation VARCHAR(100) NOT NULL, manager_id INT REFERENCES employees(id) ON DELETE SET NULL, joining_date DATE NOT NULL DEFAULT CURRENT_DATE, employment_type VARCHAR(20) NOT NULL DEFAULT 'Full Time', salary NUMERIC(12,2) DEFAULT 0, status VARCHAR(20) NOT NULL DEFAULT 'Active', created_at TIMESTAMPTZ DEFAULT now(), updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS attendance (id SERIAL PRIMARY KEY, employee_id INT NOT NULL REFERENCES employees(id) ON DELETE CASCADE, attendance_date DATE NOT NULL, check_in TIME, check_out TIME, working_hours NUMERIC(4,2), status VARCHAR(20) NOT NULL, created_at TIMESTAMPTZ DEFAULT now(), UNIQUE(employee_id, attendance_date));
CREATE TABLE IF NOT EXISTS leave_requests (id SERIAL PRIMARY KEY, employee_id INT NOT NULL REFERENCES employees(id) ON DELETE CASCADE, leave_type VARCHAR(30) NOT NULL, start_date DATE NOT NULL, end_date DATE NOT NULL, reason TEXT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'Pending', rejection_reason TEXT, reviewed_by INT REFERENCES users(id), created_at TIMESTAMPTZ DEFAULT now(), CHECK(end_date >= start_date));
CREATE TABLE IF NOT EXISTS payroll (id SERIAL PRIMARY KEY, employee_id INT NOT NULL REFERENCES employees(id) ON DELETE CASCADE, pay_month DATE NOT NULL, basic_salary NUMERIC(12,2) NOT NULL, allowances NUMERIC(12,2) DEFAULT 0, bonus NUMERIC(12,2) DEFAULT 0, tax NUMERIC(12,2) DEFAULT 0, deductions NUMERIC(12,2) DEFAULT 0, net_salary NUMERIC(12,2) NOT NULL, pay_date DATE, payment_status VARCHAR(20) DEFAULT 'Pending', created_at TIMESTAMPTZ DEFAULT now(), UNIQUE(employee_id,pay_month));
CREATE TABLE IF NOT EXISTS performance_reviews (id SERIAL PRIMARY KEY, employee_id INT NOT NULL REFERENCES employees(id) ON DELETE CASCADE, reviewer_id INT REFERENCES users(id), review_period VARCHAR(80) NOT NULL, technical_rating NUMERIC(3,1), communication_rating NUMERIC(3,1), teamwork_rating NUMERIC(3,1), leadership_rating NUMERIC(3,1), overall_rating NUMERIC(3,1), comments TEXT, goals TEXT, achievements TEXT, created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS documents (id SERIAL PRIMARY KEY, employee_id INT NOT NULL REFERENCES employees(id) ON DELETE CASCADE, name VARCHAR(160) NOT NULL, document_type VARCHAR(50), file_path TEXT NOT NULL, uploaded_by INT REFERENCES users(id), created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS notifications (id SERIAL PRIMARY KEY, user_id INT NOT NULL REFERENCES users(id) ON DELETE CASCADE, title VARCHAR(160) NOT NULL, message TEXT NOT NULL, is_read BOOLEAN DEFAULT false, created_at TIMESTAMPTZ DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_employees_dept ON employees(department_id); CREATE INDEX IF NOT EXISTS idx_attendance_date ON attendance(attendance_date); CREATE INDEX IF NOT EXISTS idx_leaves_status ON leave_requests(status);
